// ==========================================
// DHT22 (AM2302): เซ็นเซอร์วัดอุณหภูมิและความชื้น
// ติดตั้ง Library: 'DHT sensor library' โดย Adafruit ใน Library Manager
// แก้ไขหมายเลขขา DHTPIN ด้านล่างตามวงจรของคุณได้ทันที
// ==========================================
#include <DHT.h>

#define DHTPIN   4        // กำหนดขาที่ต่อกับขา DATA ของเซ็นเซอร์ (เช่น ขา 4 หรือ D4)
#define DHTTYPE  DHT22    // ระบุรุ่นเซ็นเซอร์เป็น DHT22 (AM2302)

DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  Serial.println("--- DHT22 Sensor Starting ---");
  dht.begin(); // เริ่มต้นการทำงานของเซ็นเซอร์
}

void loop() {
  // DHT22 ต้องการเวลาอ่านค่าห่างกันอย่างน้อย 2 วินาที
  delay(2000);

  float humidity = dht.readHumidity();       // อ่านค่าความชื้นสัมพัทธ์ (%)
  float temperature = dht.readTemperature(); // อ่านค่าอุณหภูมิเซลเซียส (°C)

  // ตรวจสอบว่าอ่านค่าสำเร็จหรือไม่
  if (isnan(humidity) || isnan(temperature)) {
    Serial.println("Warning: อ่านค่าจาก DHT22 ไม่สำเร็จ! กรุณาตรวจสายไฟและขา DATA");
    return;
  }

  Serial.print("ความชื้น: ");
  Serial.print(humidity, 1);
  Serial.print(" %RH\t| อุณหภูมิ: ");
  Serial.print(temperature, 1);
  Serial.println(" *C");
}
